-- Constraint/index parity gate. Non-destructive; production execution requires DBA review.
CREATE INDEX IF NOT EXISTS idx_products_company_id ON products(company_id);
CREATE INDEX IF NOT EXISTS idx_website_products_company_slug ON website_products(company_id, slug);
CREATE INDEX IF NOT EXISTS idx_website_posts_company_slug ON website_posts(company_id, slug);

-- Remaining canonical table presence declarations. Detailed columns/defaults are
-- maintained in the contract and must be expanded without destructive changes.
CREATE TABLE IF NOT EXISTS users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS companies (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, owner_id BIGINT NOT NULL, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS company_users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, user_id BIGINT NOT NULL, role TEXT NOT NULL DEFAULT 'owner', created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP, UNIQUE(company_id,user_id));
CREATE TABLE IF NOT EXISTS platform_accounts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, platform_key TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS transactions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, gross_amount NUMERIC(18,2) DEFAULT 0, profit NUMERIC(18,2) DEFAULT 0, note TEXT);
CREATE TABLE IF NOT EXISTS invoices (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, invoice_no TEXT NOT NULL, amount_incl_tax NUMERIC(18,2) DEFAULT 0);
CREATE TABLE IF NOT EXISTS products (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, sku TEXT, name TEXT, price NUMERIC(18,2) DEFAULT 0, cost NUMERIC(18,2) DEFAULT 0);
CREATE TABLE IF NOT EXISTS job_site_payments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, job_site_id BIGINT NOT NULL, amount NUMERIC(18,2) DEFAULT 0);
CREATE TABLE IF NOT EXISTS job_site_estimate_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, job_site_id BIGINT NOT NULL, quantity NUMERIC(18,4) DEFAULT 0, unit_price NUMERIC(18,2) DEFAULT 0);
CREATE TABLE IF NOT EXISTS vouchers (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, purpose TEXT, tax_amount NUMERIC(18,2) DEFAULT 0, status TEXT, type TEXT, tax NUMERIC(18,2), voucher_date DATE, note TEXT);
CREATE TABLE IF NOT EXISTS journal_entries (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS journal_lines (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, journal_entry_id BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS leads (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, title TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tender_sync_runs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, source TEXT, status TEXT, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tender_keywords (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, keyword TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS tender_watch_keywords (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, keyword TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tender_radar_sync_states (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL UNIQUE, status TEXT);
CREATE TABLE IF NOT EXISTS tender_matches (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tender_id BIGINT NOT NULL, company_id BIGINT);
CREATE TABLE IF NOT EXISTS platform_settings (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE IF NOT EXISTS user_login_logs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS visitor_logs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, visitor_id TEXT, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS traffic_events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, visitor_id TEXT, event_type TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS company_feature_overrides (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, feature_key TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS commerce_site_settings (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL UNIQUE, site_status TEXT DEFAULT 'draft');
CREATE TABLE IF NOT EXISTS commerce_site_products (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, name TEXT NOT NULL, price NUMERIC(18,2) DEFAULT 0);
CREATE TABLE IF NOT EXISTS commerce_site_promotions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, title TEXT NOT NULL, is_active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS website_banners (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, title TEXT, image_url TEXT);
CREATE TABLE IF NOT EXISTS website_home_sections (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, section_type TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS website_faqs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, question TEXT NOT NULL, answer TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS website_inquiries (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, message TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS website_assets (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, file_url TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS suppliers (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS customers (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS purchase_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, purchase_id BIGINT NOT NULL, unit_price NUMERIC(18,2), unit_cost NUMERIC(18,2), subtotal NUMERIC(18,2));
CREATE TABLE IF NOT EXISTS purchase_payments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, purchase_id BIGINT NOT NULL, amount NUMERIC(18,2) DEFAULT 0);
CREATE TABLE IF NOT EXISTS sale_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, sale_id BIGINT NOT NULL, unit_price NUMERIC(18,2), unit_cost_snapshot NUMERIC(18,2), cost_subtotal NUMERIC(18,2));
CREATE TABLE IF NOT EXISTS sale_receipts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, sale_id BIGINT NOT NULL, amount NUMERIC(18,2) DEFAULT 0);
CREATE TABLE IF NOT EXISTS feedbacks (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT NOT NULL, message TEXT, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT, action TEXT, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
